import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, distance, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Shape, ExtrudeGeometry, PlaneGeometry, Mesh, Color, DirectionalLight, PointLight } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'primary-cta';

  // ---- rounded-rect extruded button body -------------------------------
  const w = 1.7;
  const h = 0.46;
  const r = 0.09;
  const depth = 0.12;

  const shape = new Shape();
  shape.moveTo(-w / 2 + r, -h / 2);
  shape.lineTo(w / 2 - r, -h / 2);
  shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
  shape.lineTo(w / 2, h / 2 - r);
  shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
  shape.lineTo(-w / 2 + r, h / 2);
  shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
  shape.lineTo(-w / 2, -h / 2 + r);
  shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);

  const extrudeGeo = new ExtrudeGeometry(shape, {
    depth,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.02,
    bevelSegments: 3,
    curveSegments: 8,
  });
  extrudeGeo.translate(0, 0, -depth / 2);

  const bodyMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.paper),
    roughness: 0.55,
    metalness: 0.4,
    clearcoat: 0.2,
    clearcoatRoughness: 0.6,
  });

  const bodyMesh = new Mesh(extrudeGeo, bodyMat);
  bodyMesh.castShadow = false;
  group.add(bodyMesh);

  // ---- thin accent edge stripe (<=10% of frame, signal red) ------------
  const stripeGeo = new PlaneGeometry(w * 0.92, 0.045);
  const stripeMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.5,
    metalness: 0.2,
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.9,
  });
  const stripe = new Mesh(stripeGeo, stripeMat);
  stripe.position.set(0, -h / 2 + 0.06, depth / 2 + 0.001);
  group.add(stripe);

  // ---- decorative orb (image asset) -------------------------------------
  const orbGeo = new PlaneGeometry(0.34, 0.34);
  const orbMat = new MeshStandardNodeMaterial({
    color: new Color('#ffffff'),
    roughness: 0.4,
    metalness: 0.1,
    transparent: true,
    emissive: new Color(colors.paper),
    emissiveIntensity: 1.1,
  });
  const orbMesh = new Mesh(orbGeo, orbMat);
  orbMesh.position.set(-w / 2 - 0.28, 0, 0);
  group.add(orbMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      orbMat.map = tex;
      orbMat.emissiveMap = tex;
      orbMat.needsUpdate = true;
    });
  }

  // ---- contact shadow (radial falloff via TSL) --------------------------
  const shadowRadius = Math.max(w, h) * 1.3;
  const shadowGeo = new PlaneGeometry(shadowRadius * 2, shadowRadius * 2);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const center = vec2(0.5, 0.5);
  const d = distance(uv(), center);
  const falloff = float(1.0).sub(smoothstep(0.18, 0.5, d));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = falloff.mul(0.45);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -h / 2 - 0.02, -0.02);
  group.add(shadowMesh);

  // ---- node-local rim light carrying accent hue -------------------------
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.9);
  rimLight.position.set(-1.2, 0.6, -1.0);
  group.add(rimLight);

  const fillPoint = new PointLight(new Color(colors.paper), 0.5, 3.0);
  fillPoint.position.set(0.8, 0.4, 1.0);
  group.add(fillPoint);

  // ---- placement -----------------------------------------------------
  const pos = config.scenePosition ?? { x: 0, y: -2.85, z: 0.2 };
  const rot = config.sceneRotation ?? { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale ?? { x: 1, y: 1, z: 1 };
  group.position.set(pos.x ?? 0, pos.y ?? -2.85, pos.z ?? 0.2);
  group.rotation.set(rot.x ?? 0, rot.y ?? 0, rot.z ?? 0);
  group.scale.set(scl.x ?? 1, scl.y ?? 1, scl.z ?? 1);

  // ---- weighted entrance (static composition, no perpetual motion) -----
  group.scale.multiplyScalar(0.001);
  group.position.y -= 0.15;
  const baseScale = { x: scl.x ?? 1, y: scl.y ?? 1, z: scl.z ?? 1 };
  const baseY = pos.y ?? -2.85;

  const tl = gsap.timeline();
  tl.to(group.scale, {
    x: baseScale.x,
    y: baseScale.y,
    z: baseScale.z,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(group.position, {
    y: baseY,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);

  // ---- apply cinematic primitives (none configured for this node) ------
  const primitiveHandles = [];
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      const handle = fn(group, p.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- userData handlers/cleanup ---------------------------------------
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    for (const h of primitiveHandles) {
      try { h.cleanup?.(); } catch (e) { /* noop */ }
    }
    extrudeGeo.dispose();
    stripeGeo.dispose();
    orbGeo.dispose();
    shadowGeo.dispose();
    bodyMat.dispose();
    stripeMat.dispose();
    orbMat.dispose();
    shadowMat.dispose();
    if (orbMat.map) orbMat.map.dispose();
    if (orbMat.emissiveMap) orbMat.emissiveMap.dispose();
    group.remove(rimLight);
    group.remove(fillPoint);
  };

  return group;
}
